--region init
function JapaneseStoryStageDialog:InitHandler()
    SetButtonAction(self.FontStyleButton, Bind(self, self.ConfirmButtonOnClickHandler))
end

function JapaneseStoryStageDialog:InitData()
    local parameters = checkTable(self.controller.Argument.parameters)
    
    local chapterIdx , stageIdx = JapaneseStoryMgr:GetMapStatus()
    self:SetChapterIdx(chapterIdx or parameters.chapterIdx)
    self:InitStageData()
    local new = JapaneseStoryMgr:GetNewQuestStatus()
    if chapterIdx and not new then
        self:SetSelectedStageIndex(stageIdx)
    end
    JapaneseStoryMgr:ClearMapStatus()

    if new then
        -- 最后一关完成时要返回章节选择
        local stageData = self:GetStageData()
        local endData = stageData[#stageData]
        if endData.status == JapaneseStoryConstants.QuestStatus.PASS then
            CfUtils.DialogBack()
        end
    end
end

function JapaneseStoryStageDialog:InitStageData()
    local questVo = JapaneseStoryMgr:GetQuestVo()
    local chapterIdx = self:GetChapterIdx()
    local data = JapaneseStoryMgr:GetMainQuestMap()[chapterIdx]
    local stageData = clone(questVo[tostring(data.questId)])
    local isNew = true
    local mainQuestId = JapaneseStoryMgr:GetMainQuestId()
    for i, v in ipairs(stageData) do
        if mainQuestId < v.id then
            if isNew then
                isNew = false
                v.status = JapaneseStoryConstants.QuestStatus.NOW -- 新解锁
                self:SetSelectedStageIndex(i)
            else
                v.status = JapaneseStoryConstants.QuestStatus.LOCK -- 锁定
            end
        else
            v.status = JapaneseStoryConstants.QuestStatus.PASS -- 已通关
            self:SetSelectedStageIndex(i)
        end
    end
    
    self:SetStageData(stageData)
end

function JapaneseStoryStageDialog:InitView()
    self:RefreshUI()
    -- 读取标记
    local cardWinValue = CfUtils.CookieLoad(CARD_WIN_COOKIE_KEY)
    -- 覆写标记
    CfUtils.CookieSave(CARD_WIN_COOKIE_KEY, nil)
    -- 是否打牌胜利回来
    if not string.isEmpty(cardWinValue) then
        local tempValues = string.split2(cardWinValue, ';')
        local vo = JapaneseStoryMgr:GetPlotVoById(tempValues[2])
        if checkNumber(vo.plotIdEndWave[1]) > 0 then
            -- 打牌前剧情
            JapaneseStoryMgr:PlayingPlot(vo.plotIdEndWave, function ()
                GameUtils.Request(Interfaces.JapaneseStoryCard, {activityUuid = tempValues[1], questId = tempValues[2]}, Bind(self, self.CardResponseHandler))
            end)
        else
            GameUtils.Request(Interfaces.JapaneseStoryCard, {activityUuid = tempValues[1], questId = tempValues[2]}, Bind(self, self.CardResponseHandler))
        end
    end
end
--endregion init

--region handler
---关卡列表处理
function JapaneseStoryStageDialog:OnGetItemByIndex(listView, idx)
    local index = idx + 1
    local cell = listView:NewListViewItem("ActivityJapaneseStoryChapterList")
    local scr = CfUtils.GetLuaScr(cell, JapaneseStoryConstants.ScrPath.JapaneseStoryStageCell)
    if not isNull(scr) then
        local data = self:GetStageData()[index]
        scr:RefreshCell(data, self:GetSelectedStageIndex() == index, index, Bind(self, self.CellOnClickHandler))
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            scr:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            scr:PlayAnimByIdle()
        end
    end
    return cell
end

---cell点击回调
function JapaneseStoryStageDialog:CellOnClickHandler(index)
    if index == self:GetSelectedStageIndex() then return end

    self:SetSelectedStageIndex(index)
    self:RefreshUI()
end

---确认按钮点击回调
function JapaneseStoryStageDialog:ConfirmButtonOnClickHandler()
    local data = self:GetStageData()[self:GetSelectedStageIndex()]
    if data.status == JapaneseStoryConstants.QuestStatus.LOCK then return end
    
    local isGet = data.status == JapaneseStoryConstants.QuestStatus.PASS
    local vo = JapaneseStoryMgr:GetPlotVoById(data.id)
    JapaneseStoryMgr:SaveMapStatus(self:GetChapterIdx(), self:GetSelectedStageIndex())
    local activityId = JapaneseStoryMgr:GetActivityId()
    if checkInt(data.type) == JapaneseStoryConstants.QuestPlotType.STORY then
        -- 纯剧情
        JapaneseStoryMgr:PlayingPlot(vo.plotIdStory, function ()
            if not isGet then
                GameUtils.Request(Interfaces.JapaneseStoryPlot, {activityUuid = activityId, questId = vo.id}, Bind(self, self.PlotResponseHandler))
            end
        end)
    elseif checkInt(data.type) == JapaneseStoryConstants.QuestPlotType.BATTLE then
        if isGet then
            JapaneseStoryMgr:PlayingPlot(vo.plotIdWave, function ()
                JapaneseStoryMgr:PlayingPlot(vo.plotIdEndWave)
            end)
            return
        end
        -- 开始战斗
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = data.id, activityUuid = activityId } }, {
            { id = Constants.UITypeIds.ActivityJapaneseStoryChapterDialog },
        })
    elseif checkInt(data.type) == JapaneseStoryConstants.QuestPlotType.CARD then
        if checkNumber(vo.plotIdWave[1]) > 0  then
            -- 打牌前剧情
            JapaneseStoryMgr:PlayingPlot(vo.plotIdWave, function ()
                ---@type JapaneseStoryQuestVo
                local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6495, "JapaneseStoryQuestVo", data.id)
                CfUtils.DialogOpen(Constants.UITypeIds.UIActivityJapanesePokerChooseDialog, {
                    npcId    = questVo.battleCardNpcId,
                    resultCb = function(isWin)
                        if isWin then
                            CfUtils.CookieSave(CARD_WIN_COOKIE_KEY, string.fmt('%1;%2', activityId, vo.id))
                        end
                    end
                }, { UIArgs(Constants.UITypeIds.ActivityJapaneseStoryChapterDialog) })
            end)
        else
            ---@type JapaneseStoryQuestVo
            local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6495, "JapaneseStoryQuestVo", data.id)
            CfUtils.DialogOpen(Constants.UITypeIds.UIActivityJapanesePokerChooseDialog, {
                npcId    = questVo.battleCardNpcId,
                resultCb = function(isWin)
                    if isWin then
                        CfUtils.CookieSave(CARD_WIN_COOKIE_KEY, string.fmt('%1;%2', activityId, vo.id))
                    end
                end
            }, { UIArgs(Constants.UITypeIds.ActivityJapaneseStoryChapterDialog) })
        end
    end
end

---观看主线剧情response处理
function JapaneseStoryStageDialog:PlotResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    local jsonData = response.data
    local rewards = jsonData.rewards

    JapaneseStoryMgr:SetMainQuestId(jsonData.newMainQuestId)
    self:InitStageData()
    self:RefreshUI()
    JapaneseStoryMgr:ClearMapStatus()

    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards , cb = function()
            local stageData = self:GetStageData()
            local endData = stageData[#stageData]
            if endData.status == JapaneseStoryConstants.QuestStatus.PASS then
                CfUtils.DialogBack()
            end
        end} })
    end
end

---通关主线打牌response处理
function JapaneseStoryStageDialog:CardResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    local jsonData = response.data
    local rewards = jsonData.rewards
    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end

    -- --- 更新体力
    -- local newHp = checkNumber(response.hp)
    -- GoodsUtils.DrawRewards({
    --     { goodsId = Constants.Currency.HpId, num = newHp - GoodsUtils.GetThingNo(Constants.Currency.HpId) }
    -- })
    
    local mainQuestId = JapaneseStoryMgr:GetMainQuestId()
    if checkInt(jsonData.newMainQuestId) > mainQuestId then
        JapaneseStoryMgr:SetMainQuestId(jsonData.newMainQuestId)
        JapaneseStoryMgr:ClearMapStatus()
        self:InitStageData()
        
        -- 最后一关完成时要返回章节选择
        local stageData = self:GetStageData()
        local endData = stageData[#stageData]
        if endData.status == JapaneseStoryConstants.QuestStatus.PASS then
            CfUtils.DialogBack()
        end
    end
    
    self:RefreshUI()
end
