function JapaneseStoryStageDialog:RefreshUI()
    self:RefreshStageList()
    self:RefreshStageInfo()
    self:RefreshBtn()
end

---刷新关卡列表
function JapaneseStoryStageDialog:RefreshStageList()
    local questData = self:GetStageData()
    if not self.LeftTabItem.IsListViewInit then
        self.LeftTabItem:InitListView(#questData, Bind(self, self.OnGetItemByIndex))
    else
        self.LeftTabItem.DisplayItemNumber = self.LeftTabItem.DisplayItemCount
        GameUtils.ReloadData(self.LeftTabItem, #questData)
    end
end

---刷新关卡信息
function JapaneseStoryStageDialog:RefreshStageInfo()
    local data = self:GetStageData()[self:GetSelectedStageIndex()]
    CfUtils.FillText(self.TextTitle, data.name)
    CfUtils.FillText(self.TxtDesc, data.desc)

    CfUtils.FillImage(self.ImgLevel, CfUtils.GetImageFullPath(data.pic))

    local isStory = data.type == JapaneseStoryConstants.QuestPlotType.STORY
    local isGet = data.status == JapaneseStoryConstants.QuestStatus.PASS
    local isLock = data.status == JapaneseStoryConstants.QuestStatus.LOCK
    local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting6497, "JapaneseStoryMainRewardsVo", data.id)
    local rewards = {}
    if next(rewardsVo) ~= nil then
        for i, goodsId in ipairs(rewardsVo.showItem) do
            local t = {
                goodsId = goodsId,
                num = rewardsVo.showItemNum[i]
            }
            table.insert(rewards, t)
        end
    end

    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight,  JapaneseStoryConstants.ScrPath.CommonGoodsListLight)
    scr:FreshBaseUI(rewards, false, isGet)

    CfUtils.SetActive(self.RewardNode, #rewards > 0)

    if isStory or isLock or checkInt(data.costNum) == 0 then
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    else
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, data.costItem, data.costNum)
        CfUtils.SetActive(self.CommonBtnConsumePop, not isGet)
    end
    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if isGet then
        fontStyleBtn:ResetFontStyle("B5" , localize("回顾剧情"))
        CfUtils.SetActive(self.FontStyleButton, data.type ~= 0)
    elseif isLock then
        fontStyleBtn:ResetFontStyle("B4" , '')
    else
        local btnName = isStory and localize("阅读") or localize("进入")
        fontStyleBtn:ResetFontStyle("B3" , btnName)
        CfUtils.SetActive(self.FontStyleButton, true)
    end
end

